  temps: { t: 'emeraude', d: D => D.trait('M2.4 7.4H6V10.6H10V7.4H13.6', 1.2) + D.trait('M2.4 12.6H13.6', 0.9) + D.trait('M4.8 12.6V13.4M7.2 12.6V13.4M9.6 12.6V13.4M12 12.6V13.4', 0.8) },
