/**
 * Stéréotypes non normatifs que le profil SysML de Cameo (« SysML Profile.mdzip ») range dans l'espace de noms de SysML
 * (sous-paquetages Block, Requirement, Actors, Distributions, Diagrams, Parametric, Activity de « Non-Normative Extensions »,
 * d'après l'annexe E de la spécification, et éléments dépréciés gardés par l'outil) : relevés d'après le profil livré avec
 * CATIA Magic 2026x, par leurs seuls noms. Un nom à espaces est écrit par Cameo comme un nom XML (« System context » →
 * `System_context`). Reconnus à la lecture (type affiché, famille, lignée : un «System» est un bloc, un «Sensor» un acteur,
 * un «Uniform» une propriété distribuée), jamais proposés à la création ni écrits dans un fichier qui ne les emploie pas
 * (nn : non normatif). `p` : paquetage du profil (famille) quand la lignée ne le donne pas ; `etend` : métaclasses étendues
 * en propre (celles de la lignée sont héritées).
 */
const S1_NON_NORMATIFS = {
  // Blocs (annexe E.2)
  Domain: { gen: ['Block'] }, External: { gen: ['Block'] }, System: { gen: ['Block'] }, Subsystem: { gen: ['Block'] }, System_context: { gen: ['Block'] },
  // Exigences (annexe E.3) : risque et méthode de vérification en énumérations S1_ENUMERATIONS_NN
  extendedRequirement: { gen: ['Requirement'], prop: [['source', 'String', '0..1'], ['risk', 'RiskKind', '0..1'], ['verifyMethod', 'VerificationMethodKind', '0..1']] },
  functionalRequirement: { gen: ['extendedRequirement'] }, interfaceRequirement: { gen: ['extendedRequirement'] }, performanceRequirement: { gen: ['extendedRequirement'] },
  physicalRequirement: { gen: ['extendedRequirement'] }, designConstraint: { gen: ['extendedRequirement'] },
  businessRequirement: { gen: ['extendedRequirement'] }, usabilityRequirement: { gen: ['extendedRequirement'] },
  // Acteurs : systèmes extérieurs (capteur, actionneur, système frontière, système utilisateur) et effets de l'environnement
  External_system: { etend: ['Actor'], p: 'UseCases' }, Environmental_effect: { etend: ['Actor'], p: 'UseCases' },
  Sensor: { gen: ['External_system'] }, Actuator: { gen: ['External_system'] }, Boundary_system: { gen: ['External_system'] }, User_system: { gen: ['External_system'] },
  // Paramétrique (annexe E.4) : mesure d'efficacité, fonction objectif (un bloc de contraintes ou une propriété de contrainte)
  moe: { etend: ['Property'], p: 'ConstraintBlocks' }, objectiveFunction: { etend: ['Class', 'Property'], p: 'ConstraintBlocks' },
  // Distributions (annexe E.5) : intervalle de base (min, max) spécialisé par Uniform et Interval ; Normal à part
  BasicInterval: { gen: ['DistributedProperty'], prop: [['min', 'Real', '0..1'], ['max', 'Real', '0..1']] },
  Uniform: { gen: ['BasicInterval'] }, Interval: { gen: ['BasicInterval'] },
  Normal: { gen: ['DistributedProperty'], prop: [['mean', 'Real', '0..1'], ['standardDeviation', 'Real', '0..1']] },
  // Activités : sémantique des flux (streaming, non streaming), activité essentielle, EFFBD, processus système (activité ou cas d'utilisation)
  streaming: { etend: ['Activity'], p: 'Activities' }, nonStreaming: { etend: ['Activity'], p: 'Activities' }, Essential: { etend: ['Activity'], p: 'Activities' },
  effbd: { etend: ['Activity'], p: 'Activities' }, System_process: { etend: ['Activity', 'UseCase'], p: 'Activities' },
  // Diagrammes propres à Cameo : description d'un diagramme (version, description, état d'avancement, référence), hiérarchie de blocs, usage
  ContextDiagram: { etend: ['Diagram'] }, SwimLaneDiagram: { etend: ['Diagram'] }, BlockHierarchy: { etend: ['Diagram'] }, diagramUsage: { etend: ['Diagram'] },
  Diagram_Description: { etend: ['Diagram'], prop: [['Version', 'String', '0..1'], ['Description', 'String', '0..1'], ['Completion_status', 'String', '0..1'], ['Reference', 'Element', '0..*']] },
  // Éléments dépréciés gardés par l'outil (annexe C) : extrémités d'une allocation, relations d'une exigence vues de l'élément
  Allocated: { etend: ['NamedElement'], p: 'DeprecatedElements', prop: [['allocatedFrom', 'NamedElement', '0..*', 'derive'], ['allocatedTo', 'NamedElement', '0..*', 'derive']] },
  RequirementRelated: { etend: ['NamedElement'], p: 'DeprecatedElements', prop: [['TracedFrom', 'Requirement', '0..*', 'derive'], ['Satisfies', 'Requirement', '0..*', 'derive'], ['Refines', 'Requirement', '0..*', 'derive'], ['Verifies', 'Requirement', '0..*', 'derive']] }
};
for (const [nom, s] of Object.entries(S1_NON_NORMATIFS)) {
  const general = s.gen && (S1_STEREOTYPES[s.gen[0]] || S1_NON_NORMATIFS[s.gen[0]]);
  const p = s.p || (general && general.p) || (/Diagram/.test(nom) ? 'ModelElements' : 'Blocks');
  S1_STEREOTYPES[nom] = { p, etend: s.etend || [], ...(s.gen ? { gen: s.gen } : {}), ...(s.prop ? { prop: s.prop } : {}), nn: true };
}
/** Énumérations des extensions non normatives (risque et méthode de vérification d'une exigence étendue, annexe E.3). */
const S1_ENUMERATIONS_NN = { RiskKind: ['High', 'Medium', 'Low'], VerificationMethodKind: ['Analysis', 'Demonstration', 'Inspection', 'Test'] };
Object.assign(S1_ENUMERATIONS, S1_ENUMERATIONS_NN);

/**
 * Stéréotype SysML et ceux qu'il spécialise (InterfaceBlock → Block ; Satisfy → Trace…), du plus précis au plus général.
 * @param {string} nom stéréotype
 * @returns {string[]}
 */
function s1Lignee(nom) {
  const res = [], pile = [nom];
  while (pile.length) {
    const n = pile.shift();
    if (res.includes(n)) continue;
    res.push(n);
    pile.push(...((S1_STEREOTYPES[n] && S1_STEREOTYPES[n].gen) || []).filter(g => S1_STEREOTYPES[g]));
  }
  return res;
}

/**
 * Métaclasse étendue par un stéréotype (ou par un de ceux qu'il spécialise) qui convient à un élément : attribut base_… de
 * l'application, ou null.
 * @param {string} stereo stéréotype SysML
 * @param {string} mc métaclasse de l'élément
 * @returns {string|null}
 */
function s1BaseDe(stereo, mc) {
  for (const n of s1Lignee(stereo)) {                    // InterfaceBlock étend Class par Block, Continuous étend comme Rate
    const e = S1_STEREOTYPES[n].etend.find(x => umlConforme(mc, x));
    if (e) return e;
  }
  return null;
}

/**
 * Métaclasses étendues par un stéréotype, héritées de ceux qu'il spécialise.
 * @param {string} stereo @returns {string[]}
 */
function s1Etend(stereo) { return [...new Set(s1Lignee(stereo).flatMap(n => S1_STEREOTYPES[n].etend))]; }

