  ActualOutcome: { d: "Strategic", a: "States", etend: ["InstanceSpecification"], gen: ["ActualEffect"] },
  Desirer: { d: "Strategic", a: "States", etend: ["Element"], gen: ["UAFElement"], abstrait: true },
  Desires: { d: "Strategic", a: "States", etend: ["Dependency"], gen: ["MeasurableElement"], k: [["Desires.client","Value for the client metaproperty must be stereotyped a specialization of «Desirer»."],["Desires.supplier","Value for the supplier metaproperty must be stereotyped a specialization of «ActualState»."]] },
  Effect: { d: "Strategic", a: "States", etend: ["Class"], gen: ["MotivationalElement"] },
  CapabilityRole: { d: "Strategic", a: "Structure", etend: ["Property"], gen: ["MeasurableElement","Desirer"], k: [["CapabilityRole.class","Value for class metaproperty must be stereotyped «Capability» or its specializations."],["CapabilityRole.type","Value for type metaproperty must be stereotyped «Capability» or its specializations."]] },
  StructuralPart: { d: "Strategic", a: "Structure", etend: ["Property"], gen: ["MeasurableElement"], k: [["StructuralPart.class","Value for class metaproperty must be stereotyped «StrategicPhase» or its specializations."],["StructuralPart.type","Value for type metaproperty must be stereotyped «StrategicPhase» or its specializations."]] },
  TemporalPart: { d: "Strategic", a: "Structure", etend: ["Property"], gen: ["MeasurableElement"], k: [["TemporalPart.class","Value for class metaproperty must be stereotyped «EnterprisePhase» or its specializations."],["TemporalPart.type","Value for type metaproperty must be stereotyped «EnterprisePhase» or its specializations."]] },
  Capability: { d: "Strategic", a: "Taxonomy", etend: ["Class"], gen: ["PropertySet","Desirer","SysML::Block","PhaseableElement","AffectableElement","SubjectOfStrategicConstraint"], prop: [["kind","CapabilityKind","0..1"],["customKind","String","0..1"]] },
  EnterpriseGoal: { d: "Strategic", a: "Taxonomy", etend: ["Class"], gen: ["PropertySet","SysML::Requirement","PhaseableElement","AffectableElement"], prop: [["benefit","ValueItem","0..*"]] },
