  PhaseableElement: { d: "Strategic", a: "Taxonomy", etend: ["Element"], gen: ["UAFElement"], abstrait: true },
  StrategicAsset: { d: "Strategic", a: "Taxonomy", etend: ["Class"], gen: ["Asset"], abstrait: true },
  StrategicPhase: { d: "Strategic", a: "Taxonomy", etend: ["Class"], gen: ["PropertySet","SysML::Block"] },
  ValueItem: { d: "Strategic", a: "Taxonomy", etend: ["DataType"], gen: ["MeasurementSet","StrategicAsset"], prop: [["kind","ValueItemKind","0..1"],["customKind","String","0..1"]] },
  VisionStatement: { d: "Strategic", a: "Taxonomy", etend: ["Comment"], gen: ["MeasurableElement"], k: [["VisionStatement.ownedAttribute","Values for annotatedElement metaproperty must be stereotyped «EnterpriseVision» or its specializations."]] },
  WholeLifeEnterprise: { d: "Strategic", a: "Taxonomy", etend: ["InstanceSpecification"], gen: ["ActualEnterprisePhase"] },
