  Exhibits: { d: "Strategic", a: "Traceability", etend: ["Abstraction"], gen: ["MeasurableElement","SysML::Allocate"], prop: [["environmentalConditions","Environment","0..*"]], k: [["Exhibits.client","Value for the client metaproperty must be stereotyped a specialization of «CapableElement»."],["Exhibits.supplier","Value for the supplier metaproperty must be stereotyped «Capability»."]] },
  MapsToCapability: { d: "Strategic", a: "Traceability", etend: ["Abstraction"], gen: ["MeasurableElement","SysML::Allocate"], k: [["MapsToCapability.client","Value for the client metaproperty must be stereotyped a specialization of «Activity»."],["MapsToCapability.supplier","Value for the supplier metaproperty must be stereotyped «Capability»."]] },
  OrganizationInPhase: { d: "Strategic", a: "Traceability", etend: ["Abstraction"], gen: ["MeasurableElement","SysML::Allocate"], k: [["OrganizationInEnterprise.supplier","Value for the supplier metaproperty must be stereotyped by any of specializations of «ActualStrategicPhase»."],["OrganizationInEnterprise.client","Value for the client metaproperty must be stereotyped «ActualOrganization» or its specializations."]] },
  ArchitecturalDescription: { d: "Summary and Overview", a: "", etend: ["Package"], gen: ["MeasurableElement"], prop: [["approvalAuthority","String","0..*"],["architect","String","0..*"],["assumptionAndConstraint","String","0..*"],["creatingOrganization","String","0..*"],["dateCompleted","String","0..1"],["purpose","String","0..*"],["recommendations","String","0..*"],["summaryOfFindings","String","0..*"],["toolsUsed","String","0..*"],["toBe","Boolean","1"],["architectureFramework","String","1"],["view","View","0..*"],["viewpoint","Viewpoint","0..*"],["methodologyUsed","String","0..*"],["status","String","0..*"],["version","String","0..*"]] },
  Architecture: { d: "Summary and Overview", a: "", etend: ["Class"], gen: ["UAFElement"], abstrait: true, prop: [["describedBy","ArchitecturalDescription","0..*"]] },
