  Phases: { d: "Summary and Overview", a: "", etend: ["Abstraction"], gen: ["MeasurableElement"], k: [["Phases.client","Value for the client metaproperty must be stereotyped by any of specializations of «ActualStrategicPhase»."],["Phases.supplier","Value for the supplier metaproperty must be stereotyped by any of specializations of «PhaseableElement»."]] },
  Stakeholder: { d: "Summary and Overview", a: "", etend: ["Element"], gen: ["UAFElement"], abstrait: true, prop: [["stakeholderConcern","Concern","0..*"]] },
